figure.sourcecode:
context-manifest = { "call_id": tstr, ? "task_id": tstr, ? "thought_id": tstr, "thought_kind": "seed" / "followup" / "guidance", "retry_index": uint, "stage": stage-name, "stage_role": "drafter" / "second_pass" / "evaluator" / "judge", "response_model": tstr, ? "max_tokens_sent": uint, "policy_version": uint, "policy_sha256": digest, "assembler_version": tstr, "guard_mode": "fail_closed" / "strip_and_incident", "guard_violations": [* guard-violation], "segments": [* segment-record], "messages_sha256": digest, ? "messages_digest_form": messages-digest-form, ? "sent_messages_match": bool, ? "language": language-tag, "locale_fallbacks": [* tstr], "provider_capture": provider-capture, ? "provider_mode": tstr, "provider_kwargs_added": [* tstr], }
stage-name = tstr .regexp "[a-z][a-z0-9_]{0,31}" digest = bstr .size 32 language-tag = tstr
segment-record = { "segment_id": tstr, "kind": kind, ? "provenance": provenance, "source": source, "trust": "untrusted" / "verified" / "system", "lifecycle": "standing" / "per-task" / "per-message" / "per-thought" / "retry-only" / "per-call", ? "authn": authn, ? "authz": authz, ? "acct": acct, "message_index": uint, "span_start": uint, "span_end": uint, "sha256": digest, "truncated": bool, "derived_from": [* tstr], "form": "full" / "stub", ? "stub": stub, ? "withheld_sha256": digest, ? "locale": language-tag, "locale_basis": "declared" / "assembler_rendered" / "unstated", }
kind = "stage_instruction" / "schema_instruction" / "accord" / "identity_base" / "amendment" / "rule" / "wa_guidance" / "request" / "history" / "sender_identity" / "display_name" / "action_record" / "draft" / "dma_output" / "conscience_feedback" / "tool_output" / "pipeline_position"
provenance = "user_chat" / "wa_chat" / "signed_guidance" / "amendment"
source = "user_input" / "adapter_metadata" / "auth_context" / "signed_row" / "agent_profile" / "engine" / "llm_output" / "tool_output" / "provider_lib"
authn = { "subject_id": tstr, "role": tstr, "verifier": tstr, }
authz = { "grant_kind": "amendment" / "deferral" / "response_attestation", "grant_id": tstr, ? "authorizer_id": tstr, "signature_verified": bool, "attestation_ids": [* tstr], ? "granted_at": tstr, }
acct = { ? "audit_entry_id": tstr, ? "row_hash": tstr, ? "trace_id": tstr, ? "veto_id": tstr, "discharge_ids": [* tstr], }
stub = { "kind": kind, ? "provenance": provenance, "source": source, "trust": "untrusted", "author_role": "OBSERVER" / "ADMIN" / "AUTHORITY" / "SYSTEM_ADMIN" / "unauthenticated", "authority": "none" / "advisory" / "signed", "scope": "this_turn" / "this_task" / "standing", "disposition": "open" / "answered" / "deferred" / "refused" / "advisory_unsigned" / "awaiting_signature" / "success" / "failure" / "prior", "transforms": [* "sanitized" / "truncated" / "normalized" / "redacted" / "coalesced"], "draft_relation": "none" / "responds_to" / "quotes", "quote_share": "0" / "<10%" / "10-50%" / ">50%", "size": "short" / "medium" / "long", "position": tstr .regexp "current|prior_[0-9]{1,4}", "digest": bstr .size 6, }
guard-violation = { "kind": "forbidden" / "missing_required" / "tainted" / "missing_carrier" / "wrong_source" / "lifecycle_mismatch" / "cross_scope" / "duplicate_segment_id" / "untrusted_bytes", "stage": stage-name, "policy_key": tstr, ? "segment_id": tstr, "detail": tstr, "action": "raised" / "stripped" / "recorded", }
messages-digest-form = "ciris-json-1" / "jcs"
provider-capture = "not_finalized" / "captured" / "no_message_change" / "unsupported_mode" / "unrecognized_change" / "unavailable"
